window.docContents[232].resolve({"/The-sharp-sub-Coulomb-commutator/#Fluctuations-of-Riesz-gases--The-sharp-sub-Coulomb-commutator--Lean-declarations-and-evidence--Verification-status":{"contents":"The whole-space and periodic sharp estimates have Lean proof terms. No separate Comparator verification record for either standalone sharp estimate is identified here.\n\nThe all-regime estimate commutator_estimate_of_packets and its identification with HRS.commutator_estimate have archived acceptance logs from nanoda and Lean’s default kernel. The recorded checks cover these two declarations.\n\nThe §6 argument uses HRS.commutator_coercivity_common_proof, which applies the all-regime estimate. The proof is supplied by the _proof declaration; the older HRS.commutator_coercivity_common declaration is separate.\n\n","context":"Fluctuations of Riesz gases\u0009The sharp sub-Coulomb commutator\u0009Lean declarations and evidence","header":"1.6.1. Verification status","id":"/The-sharp-sub-Coulomb-commutator/#Fluctuations-of-Riesz-gases--The-sharp-sub-Coulomb-commutator--Lean-declarations-and-evidence--Verification-status"}});